mapper.select:
select p.PROD_ID                as prodId,
       #{qryDate,jdbcType=DATE} as valueDate,/** 估值日期**/
       p.UNIT_VALUE             as unitValue,/** 产品单位净值**/
       p.CAPITAL                as capital,/** 实收资本**/
       p.UNIT_VALUE_T           as unitValueT,/** 产品累计单位净值**/
       p.ASSET_VALUE_MARKET     as assetValueMarket,/** 产品资产净值（按市值）**/
       p.W_YIELD                as wYield,/** 当日万份收益**/
       p.YIELD_7                as yield7,/** 7日年化收益率**/
       r.valuePercent           as valuePercent/** 本期净值收益**/
from REP_PROD_INDEX p,
     (
         SELECT (SUM(1 + p.W_YIELD / 10000) - 1) * 100 as valuePercent,
                q.PROD_ID
         FROM rep_prod_index q
         WHERE q.PROD_ID = #{prodId,jdbcType=VARCHAR}
           AND q.VALUE_DATE BETWEEN #{startReportDate,jdbcType=DATE}
             AND #{endReportDate,jdbcType=DATE}
         GROUP BY q.PROD_ID
     ) r
where p.PROD_ID = r.PROD_ID
  and p.PROD_ID = #{prodId,jdbcType=VARCHAR}
  and p.VALUE_DATE = #{qryDate,jdbcType=DATE}

select p.PROD_ID                as prodId,
       p.PROD_NAME              as prodName,
       #{qryDate,jdbcType=DATE} as valueDate,/** 估值日期**/
       p.UNIT_VALUE             as unitValue,/** 产品单位净值**/
       p.CAPITAL                as capital,/** 实收资本**/
       p.UNIT_VALUE_T           as unitValueT,/** 产品累计单位净值**/
       p.ASSET_VALUE_MARKET     as assetValueMarket,/** 产品资产净值（按市值）**/
       p.W_YIELD                as wYield,/** 当日万份收益**/
       p.YIELD_7                as yield7,/** 7日年化收益率**/
       r.valuePercent           as valuePercent/** 本期净值收益**/
from REP_PROD_INDEX_DETAIL p,
     (
         SELECT (SUM(1 + p.W_YIELD / 10000) - 1) * 100 as valuePercent,
                q.PROD_ID
         FROM REP_PROD_INDEX_DETAIL q
         WHERE q.FPROD_ID = #{prodId,jdbcType=VARCHAR}
           AND q.VALUE_DATE BETWEEN #{startReportDate,jdbcType=DATE}
             AND #{endReportDate,jdbcType=DATE}
         GROUP BY q.PROD_ID
     ) r
where p.PROD_ID = r.PROD_ID
  and p.FPROD_ID = #{prodId,jdbcType=VARCHAR}
  and p.VALUE_DATE = #{qryDate,jdbcType=DATE}

SELECT (SUM(1 + p.W_YIELD / 10000) - 1) * 100 as valuePercent
FROM rep_prod_index p
WHERE p.PROD_ID = #{prodId,jdbcType=VARCHAR}
  AND p.VALUE_DATE BETWEEN #{startReportDate,jdbcType=DATE}
    AND #{endReportDate,jdbcType=DATE}
GROUP BY p.PROD_ID

select p.PROD_ID       as prodId,
       p.REG_DATE      as regDate,/** 权益登记日/计息结束日**/
       p.TRADE_AMT     as tradeQty,/** 红利再投金额**/
       p.REG_TRADE_QTY as regTradeQty,/** 权益登记日份额**/
       p.INT_AMT       as intAmt/** 现金分红金额**/
FROM CHB_PRD_BONUS_DEAL p
WHERE p.PROD_ID = #{prodId,jdbcType=VARCHAR}
  AND p.SETTDATE_DATE BETWEEN #{startReportDate,jdbcType=DATE}
    AND #{endReportDate,jdbcType=DATE}
